 "content": "def transform(grid):
    """Stack four 3-row layers; at each cell retain the first nonzero color."""
    height, width = len(grid), len(grid[0])
    if height % 4:
        raise ValueError("expected four equal-height layers")
    layer_height = height // 4
    out = [[0] * width for _ in range(layer_height)]
    for r in range(layer_height):
        for c in range(width):
            for layer in range(4):
                color = grid[layer * layer_height + r][c]
                if color:
                    out[r][c] = color
                    break
    return out
