    """Composite the four stacked color layers by fixed color priority."""
    h, w = len(grid), len(grid[0])
    n = h // 4
    # Priority inferred from overlaps in demonstrations: 5 > 4 > 8 > 2.
    priority = {5: 4, 4: 3, 8: 2, 2: 1, 0: 0}
    out = [[0] * w for _ in range(n)]
    for r in range(n):
